import math
from sklearn.model_selection import train_test_split
from sklearn.neighbors import KNeighborsClassifier


def scale_columns(rows):
    if not rows:
        return []

    columns = len(rows[0])
    mins = [min(row[i] for row in rows) for i in range(columns)]
    maxs = [max(row[i] for row in rows) for i in range(columns)]

    scaled = []
    for row in rows:
        new_row = []
        for i, value in enumerate(row):
            span = maxs[i] - mins[i]
            if span == 0:
                new_row.append(0.0)
            else:
                new_row.append((value - mins[i]) / span)
        scaled.append(new_row)
    return scaled


