def scale_columns(rows):
    rows = [list(row) for row in rows]
    if not rows:
        return []

    number_of_columns = len(rows[0])
    smallest = [min(row[column] for row in rows) for column in range(number_of_columns)]
    largest = [max(row[column] for row in rows) for column in range(number_of_columns)]

    scaled_rows = []
    for row in rows:
        scaled_row = []
        for column, value in enumerate(row):
            span = largest[column] - smallest[column]
            if span == 0:
                scaled_row.append(0.0)
            else:
                scaled_row.append((value - smallest[column]) / span)
        scaled_rows.append(scaled_row)

    return scaled_rows


